function head(title,description,kicker='RESEARCH WORKSPACE'){return `<div class="pagehead"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${badge(title==='Research Discoveries'?'Reported':title==='Mining Laboratory'?'Planned':'Dataset-derived')}</div>`}
function card(title,subtitle,body,foot='',extra=''){return `<section class="card ${extra}"><div class="card-head"><div><h2>${title}</h2><p>${subtitle}</p></div></div><div class="card-body">${body}</div>${foot?`<div class="card-foot">${foot}</div>`:''}</section>`}
function scope(){return `${source==='compiled'?'Original compiled CSV':'ESP enriched manifest'} · ${filter.provider||'All providers'} · ${filter.population||'All ecotypes'} · ${filter.species||'All species'}`}
