function bars(items,{color=colors[0],field='',limit=8,percent=false,total=null}={}){if(!items.length)return '<div class="empty">No observations match these filters.</div>';const max=Math.max(...items.map(x=>x.count)),denom=total??sum(items);return items.slice(0,limit).map((x,i)=>`<button class="bar-row" ${field?`data-filter-field="${field}" data-filter-value="${esc(x.name)}"`:`data-bar-info="${esc(x.name)}" data-bar-count="${x.count}"`} title="${esc(x.name)}: ${fmt(x.count)}${field?' — click to filter':''}"><span class="bar-label">${esc(x.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${max?x.count/max*100:0}%;background:${Array.isArray(color)?color[i%color.length]:color}"></div></div><span class="bar-number">${percent?((x.count/(denom||1))*100).toFixed(1)+'%':fmt(x.count)}</span></button>`).join('')}
