async function showRecording(){
 if(selectedRecord===null||page!=='atlas')return;const rid=selectedRecord,epoch=sourceEpoch, cacheKey=`${source}:${rid%64}`;
 try{if(!eventsCache.has(cacheKey))eventsCache.set(cacheKey,await fetchJSON(`data/${source}/events-${rid%64}.json`));if(epoch!==sourceEpoch||page!=='atlas'||rid!==selectedRecord)return;const payload=eventsCache.get(cacheKey)[rid],r=records.find(x=>x.id===rid);const fields=['id','start','end','species','call','population','level','low','high','utc','confidence'];const all=payload.events.map(values=>Object.assign(Object.fromEntries(fields.map((k,i)=>[k,values[i]])),{provider:payload.provider}));const es=all.filter(e=>(!filter.provider||e.provider===filter.provider)&&(!filter.population||e.population===filter.population)&&(!filter.species||e.species===filter.species)&&(!eventCall||(e.call||e.species)===eventCall));const valid=es.filter(e=>e.start!==null&&e.end!==null&&e.start>=0&&e.end>=e.start);let max=Math.max(1,...valid.map(e=>e.end)),min=Math.min(0,...valid.map(e=>e.start)),width=900*zoom;let lanes=[];const plotted=valid.map(e=>{let l=lanes.findIndex(end=>end<=e.start);if(l<0)l=lanes.length;lanes[l]=e.end;return {e,l}}),labels=unique(valid.map(e=>({label:e.call||e.species})),'label');const height=Math.max(150,70+lanes.length*26);const typed=valid.filter(e=>e.species==='Killer whale'&&e.call&&!['unk','unknown'].includes(e.call.toLowerCase()));let repeated=new Set();for(let i=1;i<typed.length;i++)if(typed[i].call===typed[i-1].call){repeated.add(typed[i].id);repeated.add(typed[i-1].id)}
 $('#recording-panel').innerHTML=card('Recording event timeline',r.name,`<div class="metric-inline"><div>Events in view<strong>${fmt(es.length)}</strong></div><div>Overlap lanes<strong>${lanes.length}</strong></div><div>Annotated extent<strong>${max.toFixed(1)} s</strong></div><div>Invalid intervals omitted from plot<strong>${es.length-valid.length}</strong></div></div><div class="toolbar"><label>Zoom <input id="zoom" type="range" min="1" max="6" step=".5" value="${zoom}" aria-label="Timeline zoom"></label><label>Label <select id="event-call">${options(labels,eventCall,'All labels')}</select></label><span class="small muted">Horizontal scroll to pan · click an interval to inspect</span></div><div class="timeline-wrap"><svg class="timeline" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="group" aria-label="Real annotation intervals arranged in overlap lanes, time in seconds">${Array.from({length:11},(_,i)=>{const x=45+i*(width-75)/10;return `<line x1="${x}" x2="${x}" y1="25" y2="${height-20}" stroke="#ccd7e9"/><text x="${x}" y="16" text-anchor="middle">${(max*i/10).toFixed(1)}s</text>`}).join('')}${plotted.map(({e,l})=>{const label=e.call||e.species,idx=labels.indexOf(label),x=45+e.start/max*(width-75),w=Math.max(2,(e.end-e.start)/max*(width-75));return `<rect class="event" tabindex="0" role="button" aria-label="${esc(label)}, ${e.start} to ${e.end} seconds" data-event="${esc(e.id)}" x="${x}" y="${40+l*26}" width="${w}" height="15" rx="2" fill="${colors[idx%colors.length]}" ${repeated.has(e.id)?'stroke="#ffffff" stroke-width="1.2"':''}><title>${esc(label)} · ${e.start}–${e.end} s${repeated.has(e.id)?' · same-label adjacency':''}</title></rect>`}).join('')}</svg></div><div id="event-info" class="event-details">Select an interval to view its metadata. White outlines mark adjacent identical named labels among the filtered, valid killer whale events.</div><div class="legend">${labels.slice(0,20).map((l,i)=>`<span class="small" style="margin-right:15px;color:${colors[i%colors.length]}">● ${esc(l)}</span>`).join('')}</div>${explanation('Each interval uses the original start and end times. Overlapping annotations occupy separate lanes. Annotated extent is the last event end, not recording audio duration. Same-label highlighting is descriptive; it is recomputed on the current view and is not a significance test. Unlabeled periods can contain unannotated sounds. No audio has been downloaded.')}`,`<span>${esc(r.provider)} · ${esc(r.populations.join(', '))}</span><span>Recording ${rid} · ${esc(source)}</span>`);
 $('#zoom').oninput=e=>{zoom=+e.target.value;showRecording()};$('#event-call').onchange=e=>{eventCall=e.target.value;showRecording()};$$('[data-event]').forEach(el=>{el.onclick=()=>{const e=all.find(e=>e.id===el.dataset.event);$('#event-info').innerHTML=`<strong>${esc(e.call||e.species)}</strong> · ${esc(e.id)}<br>Start: ${e.start} s · End: ${e.end} s · Duration: ${(e.end-e.start).toFixed(3)} s<br>Frequency: ${e.low??'unavailable'}–${e.high??'unavailable'} Hz · Ecotype: ${esc(e.population)}<br>Annotation level: ${esc(e.level)||'unavailable'} · Supplied confidence: ${esc(e.confidence)||'unavailable'}<br>UTC: ${esc(e.utc)||'unavailable'}<br><span class="muted">Source recording: ${esc(payload.path)}</span>`};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.onclick()}}});
 }catch(e){if($('#recording-panel'))$('#recording-panel').innerHTML=`<div class="notice amber">Could not load recording metadata. ${esc(e.message)} <button class="text-button" id="retry-recording">Retry</button></div>`;$('#retry-recording')?.addEventListener('click',showRecording)}
}
function showCall(name,kind){const subset=rows().filter(x=>x[kind]===name),ds=subset.reduce((a,x)=>a.map((n,i)=>n+x.histogram[i]),Array(8).fill(0));const ids=new Set(subset.flatMap(x=>x.recordings));const rs=records.filter(r=>ids.has(r.id)).sort((a,b)=>b.count-a.count).slice(0,6);const next=patternRows().filter(x=>x.from===name);openDetail(`<div class="eyebrow">${kind==='call'?'NAMED CALL LABEL':'ANNOTATION CLASS'}</div><h2>${esc(name)}</h2>${badge()}<div class="metric-inline"><div>Annotations<strong>${fmt(sum(subset))}</strong></div><div>Recordings<strong>${fmt(ids.size)}</strong></div></div><p>Labels are supplied by human annotators. A call identifier alone does not establish a behavioral meaning.</p><div class="mt"><h3>Duration distribution</h3><p class="small">Valid intervals only. Event counts per duration bin.</p><div class="mt">${bars(ds.map((count,i)=>({name:['≤0.25 s','0.25–0.5 s','0.5–1 s','1–2 s','2–5 s','5–10 s','10–30 s','>30 s'][i],count})),{color:colors[1]})}</div></div><h3>Available ecotype coverage</h3><div class="mt">${bars(grouped(subset,'population'))}</div>${next.length?`<h3>Observed next-call labels</h3><div class="mt">${bars(grouped(next.map(x=>({...x,label:x.to})),'label').slice(0,5),{color:colors[2]})}</div><p class="small">Start-ordered typed killer whale events; descriptive counts, not significant motifs.</p>`:''}<h3 class="mt">Inspect a source recording</h3><div class="mt">${rs.map(r=>`<p style="margin:10px 0"><button class="text-button" data-detail-record="${r.id}">${esc(r.name)} ↗</button></p>`).join('')}</div>${sourceNote()}`);$$('[data-detail-record]').forEach(el=>el.onclick=()=>{$('#detail').close();selectedRecord=+el.dataset.detailRecord;atlasMode='recordings';page='atlas';location.hash='atlas';render();showRecording()});bindBars()}
function patternRows(){return data.transitions.filter(x=>(!filter.provider||x.provider===filter.provider)&&(!filter.population||x.population===filter.population)&&(!filter.species||filter.species==='Killer whale'))}
function pairCounts(){const counts=new Map();for(const x of patternRows()){const k=JSON.stringify([x.from,x.to]);if(!counts.has(k))counts.set(k,{from:x.from,to:x.to,count:0,overlaps:0});const r=counts.get(k);r.count+=x.count;r.overlaps+=x.overlaps}return [...counts.values()]}
function patterns(){const ps=pairCounts(),total=sum(ps),same=sum(ps.filter(x=>x.from===x.to));return `${head('Communication Patterns','Investigate observed call ordering, and the statistical tests that separate a pattern from a reliable finding.','SEQUENCES / TIMING / NULL MODELS')}
 ${reportedScope()}<div class="grid equal">${card('Repetition exceeds a shuffled baseline','Same-type adjacent pairs · fixed reference analysis',`${badge('Reported')}${repetition()}${bars([{name:'Observed',count:47.9},{name:'Randomized',count:34.8}],{color:[colors[0],colors[1]]})}<p class="chart-caption">Values above are percentages. Monte Carlo p = 1/5,001 ≈ 0.000200. Calls were shuffled within recordings, preserving label counts.</p>`,`<a href="${refURL}EXPLORATORY_FINDINGS.md" target="_blank" rel="noreferrer">Read Finding 003 ↗</a>`)}${card('Repeated calls are closer in time','Median of recording-level median start-to-start intervals',`${badge('Reported')}<div class="comparison"><div class="observed"><strong>4.44<span>s</span></strong><span>Same label</span></div><div class="baseline"><strong>7.33<span>s</span></strong><span>Label changes</span></div></div><p class="small">256 recordings with both transition kinds. Paired Wilcoxon p ≈ 2.43 × 10⁻¹². This measures start-to-start spacing, not silence between calls.</p>`,`<a href="${refURL}PATTERN_FINDINGS.md" target="_blank" rel="noreferrer">Read Finding 005 ↗</a>`)}</div>
 <div class="notice amber"><strong>0 of 224 individual directed pairs survived FDR correction.</strong> A visible transition is an observation, not a statistically established motif. The reference used Benjamini–Hochberg correction across the tested pairs.</div>
 <div class="section-label"><span>EXPLORE LOADED ANNOTATIONS</span>${badge()}</div>${total?`<div class="stats">${stat('Eligible adjacent pairs',total,'Current filters · descriptive')}${stat('Same-label pairs',same,'Within the typed-event sequence')}${stat('Same-label adjacency',(same/total*100).toFixed(1)+'%','Different eligibility from reported subset')}${stat('Distinct directed pairs',ps.length,'Observed, not significance tested')}</div><div class="toolbar"><div class="segmented"><button data-pattern-mode="network" class="${patternMode==='network'?'selected':''}">Transition network</button><button data-pattern-mode="matrix" class="${patternMode==='matrix'?'selected':''}">Transition matrix</button></div><label>Minimum count <input id="min-count" type="number" min="1" max="100000" value="${minimum}" style="width:85px"></label><label>Focus label<select id="focus-call">${options(unique(ps.map(x=>({label:x.from})).concat(ps.map(x=>({label:x.to}))),'label'),selectedCall,'All labels')}</select></label></div><div class="card"><div class="card-head"><div><h2>${patternMode==='network'?'Directed call transition network':'Conditional next-call matrix'}</h2><p>Up to 12 most connected labels after count threshold${selectedCall?` · focus ${esc(selectedCall)}`:''}</p></div>${patternMode==='matrix'?`<select id="matrix-mode" aria-label="Matrix values"><option value="probability" ${matrixMode==='probability'?'selected':''}>Probability</option><option value="count" ${matrixMode==='count'?'selected':''}>Count</option></select>`:''}</div><div class="card-body">${patternMode==='network'?network(ps):transitionMatrix(ps)}${explanation('Only valid, named killer whale annotations enter the sequence; unknown and unlabeled annotations are omitted. Events are sorted by start time and source row within each recording. Overlaps are retained and no maximum gap is imposed. The global ecotype filter selects the starting event’s supplied ecotype. Graphs are truncated for readability. Probability denominators include all outgoing pairs in the current scope, even edges hidden by the threshold. These descriptive calculations have not reproduced the reported permutation test.')}</div><div class="card-foot"><span>${esc(scope())}</span><span>Edges describe annotations, not individual whales.</span></div></div>`:`<div class="card empty"><h3>Named transition data is unavailable in this selection.</h3><p>The compiled CSV has no call-type field. A species-class sequence would not answer the call-repertoire question, so no call-transition graph is shown.</p>${catalog.some(x=>x.key==='enriched')?'<button class="button secondary" id="switch-enriched">Explore enriched call annotations ↗</button>':''}</div>`}${sourceNote()}`}
function visiblePairs(ps){let a=ps.filter(x=>x.count>=minimum&&(!selectedCall||x.from===selectedCall||x.to===selectedCall));const ranks=new Map();for(const p of a){ranks.set(p.from,(ranks.get(p.from)||0)+p.count);ranks.set(p.to,(ranks.get(p.to)||0)+p.count)}let labels=[...ranks].sort((a,b)=>b[1]-a[1]).slice(0,12).map(x=>x[0]);if(selectedCall&&!labels.includes(selectedCall))labels=[selectedCall,...labels.slice(0,11)];return {labels,pairs:a.filter(p=>labels.includes(p.from)&&labels.includes(p.to))}}
function pairDetail(p,ps){const out=sum(ps.filter(x=>x.from===p.from));openDetail(`<div class="eyebrow">OBSERVED DIRECTED TRANSITION</div><h2>${esc(p.from)} → ${esc(p.to)}</h2>${badge()}<div class="metric-inline"><div>Observed pairs<strong>${fmt(p.count)}</strong></div><div>Outgoing from ${esc(p.from)}<strong>${fmt(out)}</strong></div><div>P(next | current)<strong>${(p.count/out*100).toFixed(2)}%</strong></div></div><div class="formula">P(${esc(p.to)} | ${esc(p.from)}) = ${p.count} / ${out}</div><p>${fmt(p.overlaps)} pairs have overlapping event intervals. Observed adjacency after omitting unlabeled annotations does not establish a conversation, grammar, or semantic relationship. No significance test was run for this filtered result.</p>${sourceNote()}`)}
function network(ps){const {labels,pairs}=visiblePairs(ps);if(!pairs.length)return '<div class="empty">No pairs meet this threshold. Reduce the minimum count or change filters.</div>';const w=720,h=470,cx=w/2,cy=h/2,rad=165,pos=new Map(labels.map((x,i)=>[x,{x:cx+Math.cos(i/labels.length*Math.PI*2-Math.PI/2)*rad,y:cy+Math.sin(i/labels.length*Math.PI*2-Math.PI/2)*rad}]));const max=Math.max(...pairs.map(x=>x.count));return `<div class="network"><svg viewBox="0 0 ${w} ${h}" role="group" aria-label="Directed call transitions; edge width represents observed count"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#648bd7"/></marker></defs><circle cx="${cx}" cy="${cy}" r="${rad}" fill="none" stroke="#ccd7e9" stroke-dasharray="3 7"/>${pairs.map(p=>{const a=pos.get(p.from),b=pos.get(p.to);let path;if(p.from===p.to)path=`M${a.x-9},${a.y-13}C${a.x-65},${a.y-75} ${a.x+65},${a.y-75} ${a.x+9},${a.y-13}`;else{const dx=b.x-a.x,dy=b.y-a.y,l=Math.hypot(dx,dy),ex=b.x-dx/l*20,ey=b.y-dy/l*20;path=`M${a.x},${a.y}Q${cx+(a.x+b.x-2*cx)*.12},${cy+(a.y+b.y-2*cy)*.12} ${ex},${ey}`}return `<path d="${path}" fill="none" stroke="#648bd7" stroke-width="${.6+Math.sqrt(p.count/max)*4}" opacity="${.25+.5*p.count/max}" marker-end="url(#arrow)" data-pair="${esc(JSON.stringify([p.from,p.to]))}"><title>${esc(p.from)} → ${esc(p.to)}: ${fmt(p.count)} pairs</title></path>`}).join('')}${labels.map((x,i)=>{const p=pos.get(x),count=sum(ps.filter(y=>y.from===x||y.to===x));return `<circle cx="${p.x}" cy="${p.y}" r="${12+Math.min(10,Math.log10(count+1)*2)}" fill="${colors[i%colors.length]}" fill-opacity=".85" data-network-call="${esc(x)}"><title>${esc(x)} · ${fmt(count)} incident transition counts</title></circle><text x="${p.x}" y="${p.y+36}" text-anchor="middle">${esc(x.length>24?x.slice(0,21)+'…':x)}</text>`}).join('')}</svg></div><p class="chart-caption">Arrow: observed direction · edge width: pair count · node size: incident pair count · click an edge for counts and probability, a node to focus.</p>`}
function transitionMatrix(ps){const {labels,pairs}=visiblePairs(ps),map=new Map(pairs.map(p=>[JSON.stringify([p.from,p.to]),p]));if(!pairs.length)return '<div class="empty">No pairs meet this threshold.</div>';const max=Math.max(...pairs.map(p=>p.count));return `<div class="table-wrap"><table class="matrix"><thead><tr><th>FROM ↓ / TO →</th>${labels.map(l=>`<th title="${esc(l)}">${esc(l)}</th>`).join('')}</tr></thead><tbody>${labels.map(a=>{const out=sum(ps.filter(p=>p.from===a));return `<tr><th class="row-head">${esc(a)}</th>${labels.map(b=>{const p=map.get(JSON.stringify([a,b])),v=p?(matrixMode==='count'?p.count:p.count/out):0;return `<td style="background:rgba(92,131,215,${p?.10+.30*(matrixMode==='count'?p.count/max:v):.015})">${p?`<button data-pair="${esc(JSON.stringify([a,b]))}" title="${esc(a)} → ${esc(b)}: ${p.count} observations">${matrixMode==='count'?fmt(v):(v*100).toFixed(1)+'%'}</button>`:'—'}</td>`}).join('')}</tr>`}).join('')}</tbody></table></div><p class="chart-caption">Dashes mean not displayed at the current threshold. Percentages use all outgoing transitions, so visible rows may sum to less than 100%.</p>`}
function populations(){const a=rows().filter(x=>x.species==='Killer whale'),pops=unique(a.filter(x=>x.population!=='Unassigned'),'population');if(!pops.includes(popA))popA=pops[0]||'';if(!pops.includes(popB))popB=pops[1]||pops[0]||'';const A=a.filter(x=>x.population===popA),B=a.filter(x=>x.population===popB),hasCalls=a.some(x=>x.call),field=hasCalls?'call':'provider';const labels=grouped(a.filter(x=>!hasCalls||x.call),field).slice(0,12).map(x=>x.name);return `${head('Population Intelligence','Compare what was annotated across ecotypes while accounting for differences in recording sources and annotation coverage.','COMPARE / STRATIFY / QUESTION')}
 <div class="notice amber"><strong>Coverage is not population abundance.</strong> Counts depend on recording effort, provider and annotation level. Ecotype similarity here is not genetic or social relatedness. Use the global provider filter to compare within a source.</div>
 ${!a.length?'<div class="card empty">No killer whale annotations match these filters.</div>':`<div class="toolbar"><label>Compare <select id="pop-a">${options(pops,popA)}</select></label><span class="muted">with</span><label><select id="pop-b" aria-label="Second ecotype">${options(pops,popB)}</select></label><div class="segmented"><button id="raw-pop" class="${!normalized?'selected':''}">Counts</button><button id="norm-pop" class="${normalized?'selected':''}">Within-ecotype %</button></div></div><div class="grid equal">${populationCard(popA,A,colors[0],hasCalls)}${populationCard(popB,B,colors[1],hasCalls)}</div>
 ${card(hasCalls?'Annotated vocal repertoire':'Provider coverage by ecotype',hasCalls?'Named killer whale labels · top 12 in current view':'Call-type labels unavailable; source coverage is shown instead',`<div class="table-wrap"><table class="matrix"><thead><tr><th>ECOTYPE</th>${labels.map(l=>`<th>${esc(l)}</th>`).join('')}</tr></thead><tbody>${pops.map(p=>{const group=a.filter(x=>x.population===p&&(!hasCalls||x.call)),total=sum(group);return `<tr><th class="row-head">${esc(p)}</th>${labels.map(l=>{const n=sum(group.filter(x=>x[field]===l)),v=n/(total||1);return `<td style="background:rgba(92,131,215,${.025+.35*v})" title="${esc(p)} / ${esc(l)}: ${fmt(n)} annotations">${normalized?(v*100).toFixed(1)+'%':fmt(n)}</td>`}).join('')}</tr>`}).join('')}</tbody></table></div><p class="chart-caption">${hasCalls?'Percentages use named killer whale annotations within each ecotype. Empty or unknown labels have not been standardized into new biological categories.':'Percentages use all killer whale annotations within each ecotype. This is provider composition, not a call repertoire.'} ${esc(scope())}.</p>`)}
 <div class="mt">${card('Source confounding check','Provider composition of the selected ecotypes',`<div class="grid equal"><div><h3>${esc(popA)}</h3><div class="mt">${bars(grouped(A,'provider'),{field:'provider',color:colors[0],percent:normalized})}</div><div><h3>${esc(popB)}</h3><div class="mt">${bars(grouped(B,'provider'),{field:'provider',color:colors[1],percent:normalized})}</div></div><div class="notice">A difference in call labels can reflect a difference in who collected or classified the recordings. The compiled CSV’s Dataset values are source coverage labels, not validated latitude/longitude coordinates.</div>`)}</div>`}${sourceNote()}`}
function populationCard(pop,a,color,hasCalls){const labels=grouped(a.filter(x=>x.call),'call'),dc=sum(a,'duration_count');return card(pop||'No ecotype','Recorded annotation coverage',`<div class="metric-inline"><div>Annotations<strong style="color:${color}">${fmt(sum(a))}</strong></div><div>Recordings<strong>${fmt(new Set(a.flatMap(x=>x.recordings)).size)}</strong></div><div>Named labels<strong>${hasCalls?labels.length:'N/A'}</strong></div></div>${hasCalls?bars(labels,{color,percent:normalized,total:sum(a.filter(x=>x.call)),limit:6}):`<p class="small">Named call labels are absent. Mean valid event duration: ${dc?(sum(a,'duration_sum')/dc).toFixed(2)+' s':'unavailable'}. Annotation levels can differ, so durations are not automatically comparable.</p>`}`,`<span>Raw annotations · no effort normalization</span>`)}
function discoveries(){return `${head('Research Discoveries','Read the research question, inspect the method, and understand what the evidence can — and cannot — support.','EVIDENCE / METHODS / LIMITATIONS')}
 <div class="notice">All findings on this page are <strong>reported by DCLDE Explorer</strong>. OrcaMind has verified the saved documentation and result files, but has not independently reproduced the statistical tests. Global filters do not alter these fixed research subsets.</div>
 ${discovery('003','Identical call labels cluster in sequence.','Non-random repetition within annotated recordings','EXPLORATORY_FINDINGS.md',`<div class="definition-grid"><div><h3>Research question</h3><p>Do identical labels occur consecutively more often than random within-recording order predicts?</p></div><div><h3>Eligible data</h3><p>276 recordings with at least three named call annotations and at least two distinct labels; 5,806 adjacent pairs.</p></div><div><h3>Method</h3><p>Shuffle label order 5,000 times within each recording. Preserve the exact label counts in every recording. Compare the aggregate identical-adjacency statistic.</p></div><div><h3>Evidence</h3><p>2,782 observed same-label pairs versus about 2,023.1 expected. No shuffle reached the observed count; corrected Monte Carlo p = 1/5,001.</p></div></div>${repetition()}<div class="formula">p = (1 + shuffles ≥ observed) / (1 + 5,000) = 1 / 5,001</div><div class="notice amber">Consistent with repeated-call bouts. Recording selection, omitted sounds and annotation practices can also create clustering. No conclusion about grammar, turn-taking, receivers or meaning follows.</div>`,true)}
 ${discovery('005','Repeated call types are closer together.','A recording-level timing comparison','PATTERN_FINDINGS.md',`<div class="definition-grid"><div><h3>Research question</h3><p>Within recordings with both pair kinds, are same-type calls temporally closer than label changes?</p></div><div><h3>Method</h3><p>One paired comparison per recording: median start-to-start interval for same-label pairs versus changed-label pairs. Paired Wilcoxon signed-rank test.</p></div><div><h3>Evidence</h3><p>256 recordings; median of recording medians 4.438 s versus 7.32975 s. Same-type spacing was shorter in 177/256 recordings. Two-sided p ≈ 2.43 × 10⁻¹².</p></div><div><h3>Limitations</h3><p>Start-to-start spacing is not the silent gap. Overlap, event duration, missed calls and annotation selection influence intervals.</p></div></div>`)}
 ${discovery('006','No specific directed motif survived correction.','A necessary negative finding','PATTERN_FINDINGS.md',`<div class="definition-grid"><div><h3>Research question</h3><p>Are specific directed call pairs enriched relative to randomized within-recording order?</p></div><div><h3>Method</h3><p>224 pairs with at least three observed and three expected transitions. 5,000 shuffles; Benjamini–Hochberg false-discovery-rate correction.</p></div><div><h3>Evidence</h3><p>0 pairs had q &lt; 0.05. Leading candidate T01 → T02 had 18 observations, expectation 10.74, raw p ≈ 0.00140 and corrected q ≈ 0.314.</p></div><div><h3>Interpretation</h3><p>Specific motifs remain research leads. A strong-looking edge on a network can arise by chance when many pairs are tested.</p></div></div><div class="notice amber mt">The general repetition finding and the lack of individually significant motifs can both be true. They ask different statistical questions.</div>`)}
 ${discovery('002','Recorded call-label richness differs within ONC.','A provider-stratified exploratory comparison','EXPLORATORY_FINDINGS.md',`<div class="definition-grid"><div><h3>Data</h3><p>ONC recordings with one ecotype and named calls. OKW: 26 recordings, median 1.5 unique labels. SRKW: 23, median 1.0. TKW: 24, median 1.0.</p></div><div><h3>Method and evidence</h3><p>Kruskal–Wallis H ≈ 11.89, p ≈ 0.00262. Holm-adjusted pairwise p: OKW/SRKW 0.00528; OKW/TKW 0.0480; SRKW/TKW 0.255.</p></div><div><h3>Interpretation</h3><p>This selected set of OKW recordings contains a somewhat richer set of supplied call labels.</p></div><div><h3>Limitations</h3><p>These are recorded annotations, not complete wild repertoires. Extra buzzer annotations overlap with another exploratory finding; this was not a preregistered test.</p></div></div>`)}
 <div class="card card-pad"><h2>Where independent reproduction begins</h2><p class="mt small">The next step is to match the reference filtering and randomization procedure exactly, record dataset hashes and seeds, and compare sample sizes before comparing p-values. Dataset-derived dashboard counts alone do not meet this standard.</p><a href="#lab" class="text-link" style="display:inline-block;margin-top:18px">Open the Mining Laboratory roadmap ↗</a></div>`}
function discovery(id,title,sub,file,body,open=false){return `<details class="card discovery" ${open?'open':''}><summary><span class="discovery-number">${id}</span><div>${badge('Reported')}<h2>${title}</h2><p>${sub}</p></div></summary><div class="discovery-content">${body}<p class="source-note">Source: <a href="${refURL}${file}" target="_blank" rel="noreferrer">DCLDE Explorer / ${file} ↗</a> · Human annotations, metadata-only research.</p></div></details>`}
function warehouse(){const a=rows(),m=data.meta,fields=Object.entries(m.missing).sort((a,b)=>b[1]-a[1]);return `${head('Data Warehouse','Trace original annotations through normalization, quality checks, dimensional tables and the aggregates used by this dashboard.','EXTRACT / TRANSFORM / EXPLAIN')}
 <div class="pipeline"><div><small>01 / RAW</small><strong>Original source</strong><p>Preserved CSV · ${fmt(m.raw_bytes)} bytes</p></div><div><small>02 / STAGING</small><strong>Typed & validated</strong><p>Missing tokens normalized. Invalid rows flagged.</p></div><div><small>03 / WAREHOUSE</small><strong>SQLite facts</strong><p>Event and transition facts; dimension views.</p></div><div><small>04 / RESEARCH</small><strong>Query-ready outputs</strong><p>Filtered cubes and lazy-loaded event blocks.</p></div></div>
 <div class="grid equal">${card('Actual ETL row accounting','Full selected source · unaffected by global filters',`<div class="table-wrap"><table><thead><tr><th>TRANSFORMATION</th><th>OUTPUT ROWS</th></tr></thead><tbody>${m.etl.map(x=>`<tr><td>${esc(x.step)}</td><td class="numeric">${fmt(x.rows)}</td></tr>`).join('')}</tbody></table></div><p class="chart-caption">No original rows are deleted. Invalid intervals remain queryable; they are excluded from duration and transition calculations. Duplicate candidates remain in the facts.</p>`)}${card('Quality diagnostics','Full selected source · rows flagged, not discarded',`<div class="metric-inline"><div>Invalid time intervals<strong>${fmt(m.issues.invalid_interval||0)}</strong></div><div>Invalid frequency bounds<strong>${fmt(m.issues.invalid_frequency_bounds||0)}</strong></div><div>Duplicate candidates<strong>${fmt(m.issues.duplicate_candidates||0)}</strong></div></div>${bars(fields.filter(([k])=>['population','call','confidence','low','high','utc'].includes(k)).map(([name,count])=>({name,count})),{color:colors[2],percent:true,total:m.events})}<p class="chart-caption">Missing/empty percentage, denominator ${fmt(m.events)} events. Call type missing in compiled data is a schema limitation. Duplicate candidates match recording, times, class, call, ecotype, level and frequency bounds.</p>`)}</div>
 ${card('Dimensional model','Implemented as event/transition fact tables and distinct dimension views',`<div class="schema"><div class="schema-group"><div class="schema-box"><strong>Dim_Recording</strong><p>source + recording_id<br>provider · location</p></div><div class="schema-box"><strong>Dim_Provider</strong><p>source · provider</p></div><div class="schema-box"><strong>Dim_Population</strong><p>source · population</p></div></div><div class="schema-group"><div class="schema-box fact"><strong>Fact_CallEvent</strong><p>Grain: one source annotation<br>recording_id · event_id<br>species · call_type · ecotype<br>start · end · duration<br>frequency bounds · quality flag</p></div><div class="schema-box fact"><strong>Fact_CallTransition</strong><p>Grain: two eligible successive events<br>from_event · to_event<br>start_spacing · end_gap<br>same_type</p></div></div><div class="schema-group"><div class="schema-box"><strong>Dim_CallType</strong><p>source · supplied call_type<br>Non-empty labels only</p></div><div class="schema-box"><strong>Dim_Location</strong><p>source · location label<br>No inferred coordinates</p></div></div></div><p class="chart-caption">Dimension views use source-qualified natural identifiers; no invented date dimension. UTC remains as supplied in event facts. The model is a first-release dimensional projection, without enforced foreign keys.</p>`)}
 <div class="mt">${card('OLAP explorer','Slice with global filters; pivot and roll up real event counts',`<div class="toolbar"><label>Rows<select id="olap-row">${options(['population','provider','species','call','level','location'],olapRow)}</select></label><label>Columns<select id="olap-col">${options(['population','provider','species','call','level','location'],olapCol)}</select></label><span class="small muted">${fmt(sum(a))} annotations · ${esc(scope())}</span></div>${olap(a)}`)}</div>
 <div class="mt">${card('Source schema & provenance','Verified file structure, raw fields, and content identity',`<p class="small">${m.fields.concat(m.selection_fields||[]).map(f=>`<code style="display:inline-block;margin:5px 7px 5px 0;color:var(--text);background:var(--code-bg);padding:5px 8px;border-radius:3px">${esc(f||'(unnamed source row index)')}</code>`).join('')}</p><div class="formula" style="font-size:10px">SHA-256 ${esc(m.sha256)}</div><p class="small">${m.utc_min?`Supplied UTC range: ${esc(m.utc_min)} — ${esc(m.utc_max)}. Provider semantics can differ; these values are not assumed to be uniformly recording-start dates.`:'Calendar timestamps are unavailable in this source. No calendar trend is inferred from within-recording offsets.'}</p><p class="source-note"><a href="${m.source_url}" target="_blank" rel="noreferrer">Source implementation / file ↗</a> · This source is kept separate from other dataset versions.</p>`)}</div>`}
function olap(a){const rowNames=grouped(a,olapRow).map(x=>x.name),colNames=grouped(a,olapCol).slice(0,12).map(x=>x.name);return `<div class="table-wrap"><table><thead><tr><th>${esc(olapRow.toUpperCase())} ↓ / ${esc(olapCol.toUpperCase())} →</th>${colNames.map(x=>`<th>${esc(x||'(unavailable)')}</th>`).join('')}<th>ROW TOTAL</th></tr></thead><tbody>${rowNames.map(r=>`<tr><td><button class="text-button" ${['population','provider','species'].includes(olapRow)?`data-filter-field="${olapRow}" data-filter-value="${esc(r)}"`:`data-bar-info="${esc(r||'(unavailable)')}" data-bar-count="${sum(a.filter(x=>x[olapRow]===r))}"`}>${esc(r||'(unavailable)')}</button></td>${colNames.map(c=>`<td class="numeric">${fmt(sum(a.filter(x=>x[olapRow]===r&&x[olapCol]===c)))}</td>`).join('')}<td class="numeric">${fmt(sum(a.filter(x=>x[olapRow]===r)))}</td></tr>`).join('')}</tbody></table></div><p class="chart-caption">Up to 12 columns shown; row totals include hidden columns. Click ecotype, provider or species row labels to drill into the workspace. Export view downloads the full filtered cube.</p>`}
function lab(){const experiments=[['01','Reproduce same-label adjacency','Match the enriched dataset version and eligibility rules, then run 5,000 within-recording permutations. Compare sample size, observed rate and null expectation before marking reproduced.','Priority next','Permutation test · seed 20260821'],['02','Recording repertoire clustering','Group recordings by scaled, normalized call-label vectors. Evaluate silhouette and stability, then inspect whether clusters mainly track providers.','Planned','K-Means · hierarchical clustering'],['03','Call co-occurrence mining','Define fixed, bounded windows as transactions. Compare Apriori and FP-Growth using support, confidence and lift, with recording effort controls.','Planned','Apriori · FP-Growth'],['04','Sequence model evaluation','Estimate conditional next-call probabilities and compare held-out recordings with a suitable baseline. Quantify sparse transitions and uncertainty.','Planned','Markov chains · grouped validation'],['05','A defensible prediction target','Use independent numerical measurements only when a reliable label is available. Split by recording to prevent leakage, and evaluate balanced accuracy and F1.','Planned','Decision tree · Naive Bayes']];return `${head('Mining Laboratory','A transparent roadmap for independent experiments. No training runs or statistical reproductions are claimed before they exist.','FROM EXPLORATION TO REPRODUCTION')}
 <div class="notice"><strong>Current capability:</strong> OrcaMind calculates descriptive counts, valid event durations, recording timelines and eligible named-call transition counts. The reference statistical tests remain reported. Experiment execution is not implemented in this release.</div><div class="grid equal">${experiments.map(([n,title,desc,status,methods])=>`<section class="card lab-card"><div style="display:flex;justify-content:space-between"><span class="eyebrow">EXPERIMENT ${n}</span>${badge('Planned')}</div><h3>${title}</h3><p>${desc}</p><div class="lab-meta">${methods} · ${status}</div></section>`).join('')}<section class="card lab-card finding-card"><div class="eyebrow">REPRODUCTION CHECKLIST</div><h3>What earns a “Reproduced” badge?</h3><p>Record the input hash, source version, eligibility criteria, algorithm, seed and sample size. Run the computation, compare it with the reference, and investigate differences without forcing a match.</p><a class="text-link" href="${refURL}src/orca_explorer/exploratory.py" target="_blank" rel="noreferrer">Inspect reference implementation ↗</a><div class="lab-meta">Negative results are valid research outcomes.</div></section></div>`}
function openDetail(html){$('#detail-content').innerHTML=html;if(!$('#detail').open)$('#detail').showModal()}
function bindBars(){$$('[data-filter-field]').forEach(el=>el.onclick=()=>{filter[el.dataset.filterField]=el.dataset.filterValue;syncControls();render()});$$('[data-bar-info]').forEach(el=>el.onclick=()=>openDetail(`<h2>${esc(el.dataset.barInfo)}</h2><p>Displayed value: ${fmt(+el.dataset.barCount)}.</p><p class="mt">See the chart title and caption for units and source scope.</p>`))}
function bind(){
 bindBars();$$('[data-atlas-mode]').forEach(el=>el.onclick=()=>{atlasMode=el.dataset.atlasMode;render()});$('#browse-recordings')?.addEventListener('click',()=>{atlasMode='recordings';render()});
 function bindSearch(id,key){const el=$(id);if(el)el.oninput=e=>{const position=e.target.selectionStart;if(key==='call')search=e.target.value;else {recordSearch=e.target.value;recordPage=0}render();$(id)?.focus();$(id)?.setSelectionRange(position,position)}}bindSearch('#call-search','call');bindSearch('#record-search','record');
 $$('[data-call-detail]').forEach(el=>{el.onclick=()=>showCall(el.dataset.callDetail,el.dataset.callKind);el.onkeydown=e=>{if(e.key==='Enter')el.onclick()}});$$('[data-record]').forEach(el=>{el.onclick=()=>{selectedRecord=+el.dataset.record;eventCall='';zoom=1;showRecording();$('#recording-panel').scrollIntoView({behavior:'smooth',block:'start'})};el.onkeydown=e=>{if(e.key==='Enter')el.onclick()}});
 $('#previous-records')?.addEventListener('click',()=>{recordPage--;render()});$('#next-records')?.addEventListener('click',()=>{recordPage++;render()});$$('[data-pattern-mode]').forEach(el=>el.onclick=()=>{patternMode=el.dataset.patternMode;render()});
 $('#min-count')?.addEventListener('change',e=>{minimum=Math.max(1,+e.target.value||1);render()});$('#focus-call')?.addEventListener('change',e=>{selectedCall=e.target.value;render()});$('#matrix-mode')?.addEventListener('change',e=>{matrixMode=e.target.value;render()});$$('[data-network-call]').forEach(el=>el.onclick=()=>{selectedCall=el.dataset.networkCall;render()});$$('[data-pair]').forEach(el=>el.onclick=()=>{const [a,b]=JSON.parse(el.dataset.pair);const ps=pairCounts(),p=ps.find(x=>x.from===a&&x.to===b);if(p)pairDetail(p,ps)});
 $('#switch-enriched')?.addEventListener('click',()=>loadSource('enriched'));$('#pop-a')?.addEventListener('change',e=>{popA=e.target.value;render()});$('#pop-b')?.addEventListener('change',e=>{popB=e.target.value;render()});$('#raw-pop')?.addEventListener('click',()=>{normalized=false;render()});$('#norm-pop')?.addEventListener('click',()=>{normalized=true;render()});$('#olap-row')?.addEventListener('change',e=>{olapRow=e.target.value;render()});$('#olap-col')?.addEventListener('change',e=>{olapCol=e.target.value;render()});
 if(page==='atlas'&&selectedRecord!==null)showRecording();
}
function syncControls(){for(const k of ['provider','population','species'])$('#'+k).innerHTML=options(unique(data.cube,k),filter[k],{provider:'All providers',population:'All ecotypes',species:'All species'}[k]);$('#source').value=source;$('#footer-source').textContent=source==='compiled'?'DCLDE / Original compiled annotations':'DCLDE / ESP enriched annotations'}
function render(){if(!data)return;$('#crumb').textContent=pages.find(x=>x[0]===page)?.[1]||'Overview';$('#nav').innerHTML=pages.map(([id,name,path])=>`<a href="#${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}>${icon(path)}${name}</a>`).join('');$('#workspace').innerHTML=({overview,atlas,patterns,populations,discoveries,warehouse,lab}[page]||overview)();bind()}
async function fetchJSON(url){const r=await fetch(url);if(!r.ok)throw Error(`Metadata request failed (${r.status}).`);return r.json()}
async function loadSource(key){sourceEpoch++;const epoch=sourceEpoch;source=key;filter={provider:'',population:'',species:''};selectedRecord=null;selectedCall='';search='';recordSearch='';recordPage=0;eventCall='';$('#workspace').innerHTML='<div class="loading">Loading source metadata…</div>';try{const [d,r]=await Promise.all([fetchJSON(`data/${key}/summary.json`),fetchJSON(`data/${key}/recordings.json`)]);if(epoch!==sourceEpoch)return;data=d;records=r;syncControls();render()}catch(e){$('#workspace').innerHTML=`<div class="card empty error"><h3>Source metadata could not be loaded.</h3><p>${esc(e.message)}</p><button class="button secondary" id="retry-source">Retry</button></div>`;$('#retry-source').onclick=()=>loadSource(key)}}
$('#menu').onclick=()=>document.body.classList.toggle('nav-open');$('#detail .dialog-close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close()});window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);page=pages.some(x=>x[0]===p)?p:'overview';document.body.classList.remove('nav-open');render();window.scrollTo({top:0})});
for(const k of ['provider','population','species'])$('#'+k).onchange=e=>{filter[k]=e.target.value;recordPage=0;render()};$('#source').onchange=e=>loadSource(e.target.value);$('#reset').onclick=()=>{filter={provider:'',population:'',species:''};syncControls();render()};
$('#export').onclick=()=>{if(!data)return;const a=rows(),columns=['provider','population','location','species','call','level','count','duration_count','duration_sum'];const body=csvText(a,columns,{source,status:'Dataset-derived',scope:scope(),sha256:data.meta.sha256});const blob=new Blob([body],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`orcamind-${source}-filtered.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};
try{[catalog,reported]=await Promise.all([fetchJSON('data/catalog.json'),fetchJSON('data/reported.json')]);$('#source').innerHTML=catalog.map(x=>`<option value="${x.key}">${x.key==='compiled'?'Original compiled CSV':'ESP enriched annotations'}</option>`).join('');page=pages.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview';await loadSource(catalog.some(x=>x.key==='enriched')?'enriched':'compiled')}catch(e){$('#workspace').innerHTML=`<div class="card empty error"><h3>Dataset catalog unavailable.</h3><p>${esc(e.message)} Serve this folder over HTTP; see the project README.</p></div>`}
